import { expect, test } from 'bun:test'

import {
  aboutProgress,
  anchorOffset,
  asteriskRadius,
  asteriskTarget,
  auroraStyle,
  bootDelay,
  cameraAngles,
  cloudCenter,
  collapseFactor,
  commandHopDelay,
