---
import { markPolygons, polyAlpha, strokeWidth } from '../lib/motion/mark'

interface Props {
  size: number
}

const { size } = Astro.props

// Projected once, here, at rest and unwobbled. This is the exact frame the canvas takes
// over from, which is why there is no jump when it mounts: same module, same numbers.
const polys = markPolygons(size, 1, 0, Math.PI / 4)
const points = (poly: (typeof polys)[number]) =>
  poly.points.map((p) => `${p.x.toFixed(2)},${p.y.toFixed(2)}`).join(' ')
---

<span class="mark" data-mark={size} aria-hidden="true">
  <svg
    width={size}
    height={size}
    viewBox={`0 0 ${size} ${size}`}
    fill="none"
    stroke="currentColor"
    data-mark-svg
  >
    {
      polys.map((poly) => {
        const alpha = polyAlpha(poly, false)
        return poly.points.length === 2 ? (
          <polyline
            points={points(poly)}
            stroke-opacity={alpha.stroke}
            stroke-width={strokeWidth(poly.kind, size)}
          />
        ) : (
          <polygon
            points={points(poly)}
            fill="currentColor"
            fill-opacity={alpha.fill}
            stroke-opacity={alpha.stroke}
            stroke-width={strokeWidth(poly.kind, size)}
          />
        )
      })
    }
  </svg>
</span>

<style>
  /* The only color the mark ever names, and it names a token. Both the SVG's
     `currentColor` and the canvas' `getComputedStyle(...).color` read it from here. */
  .mark {
    display: inline-flex;
