// ---------- knobs ----------
const K = {
  duration: { v: 4200, min: 2500, max: 12000, step: 100, label: 'duración total (ms)' },
  spread: { v: 1, min: 0.6, max: 1.8, step: 0.01, label: 'separación de piezas' },
  globalSpin: { v: 0.5, min: 0, max: 4, step: 0.05, label: 'giro del conjunto' },
  pieceSpin: { v: 1, min: 0, max: 4, step: 0.05, label: 'giro de cada pieza' },
  tilt: { v: 0.62, min: 0, max: 1.2, step: 0.01, label: 'inclinación isométrica' },
  scale: { v: 0.85, min: 0.5, max: 1.8, step: 0.01, label: 'tamaño en el hero' },
  nodes: { v: 64, min: 0, max: 120, step: 1, label: 'nodos de la red' },
}
const ON = { files: true, ticks: true, glow: true, wire: true, light: false }

const knobs = document.getElementById('knobs')
for (const [key, k] of Object.entries(K)) {
  const el = document.createElement('div')
  el.className = 'knob'
  el.innerHTML = `<label><span>${k.label}</span><b data-v="${key}">${k.v}</b></label>
    <input type="range" min="${k.min}" max="${k.max}" step="${k.step}" value="${k.v}">`
  const out = el.querySelector('b')
  el.querySelector('input').addEventListener('input', (e) => {
    k.v = +e.target.value
    out.textContent = k.v
    drawSizes()
  })
  knobs.appendChild(el)
}

document.querySelectorAll('[data-toggle]').forEach((b) => {
  b.addEventListener('click', () => {
    const key = b.dataset.toggle
    ON[key] = !ON[key]
    b.dataset.on = String(ON[key])
    if (key === 'light') document.getElementById('stage').style.setProperty('--stage-bg', ON.light ? '#f4f5f7' : '#08090c')
    drawSizes()
  })
})

